nFilterTime :=LREAL_TO_TIME(FUN_MSTOS(g_nFilterTime_Limit));
nCylFilterTime :=LREAL_TO_TIME(FUN_MSTOS(g_nFilterTime_Cyl));
(*滤波后的正负零位*)
(*X*)
Filter_46(nFilterTime,g_bXAxisZeroLogic,g_biXAxisHomeSignal,g_biFilter_XAxisZero);
Filter_47(nFilterTime,g_bXAxisPosLimitLogic,g_biXAxisPosLimit,g_biFilter_XAxisPosLimit);
Filter_48(nFilterTime,g_bXAxisNegLimitLogic,g_biXAxisNegLimit,g_biFilter_XAxisNegLimit);
(*Y*)
Filter_49(nFilterTime,g_bYAxisZeroLogic,g_biYAxisHomeSignal,g_biFilter_YAxisZero);
Filter_50(nFilterTime,g_bYAxisPosLimitLogic,g_biYAxisPosLimit,g_biFilter_YAxisPosLimit);
Filter_51(nFilterTime,g_bYAxisNegLimitLogic,g_biYAxisNegLimit,g_biFilter_YAxisNegLimit);
(*CNC U*)
Filter_52(nFilterTime,g_bCNCUAxisZeroLogic,g_biCNCUAxisHomeSignal,g_biFilter_CNCUAxisZero);
Filter_53(nFilterTime,g_bCNCUAxisPosLimitLogic,g_biCNCUAxisPosLimit,g_biFilter_CNCUAxisPosLimit);
Filter_54(nFilterTime,g_bCNCUAxisNegLimitLogic,g_biCNCUAxisNegLimit,g_biFilter_CNCUAxisNegLimit);

(*无滤波的信号用于回零*)
g_bUAxisHomeZeroSignalNoFilter := FUN_SingalLogic(g_biCNCUAxisHomeSignal,g_bCNCUAxisZeroLogic);
g_bUAxisHomePosSignalNoFilter := FUN_SingalLogic(g_biCNCUAxisPosLimit,g_bCNCUAxisPosLimitLogic);
g_bUAxisHomeNegSignalNoFilter := FUN_SingalLogic(g_biCNCUAxisNegLimit,g_bCNCUAxisNegLimitLogic);




(*滤波后的正负零位*)
Filter_1(nFilterTime,bZAxisPosLimit,g_biZAxisPosLimit,g_bFilter_ZAxisPosLimit);
Filter_2(nFilterTime,bZAxisNegLimit,g_biZAxisNegLimit,g_bFilter_ZAxisNegLimit);
Filter_3(nFilterTime,bZAxisZero,g_biZAxisZero,g_bFilter_ZAxisZero);
(*Z轴正限位*)
g_bZAxisPosLimit:= FUN_SingalLogic(g_bFilter_ZAxisPosLimit,bZAxisPosLimit );
(*Z轴负限位*)
g_bZAxisNegLimit :=FUN_SingalLogic(g_bFilter_ZAxisNegLimit,bZAxisNegLimit);
(*Z轴零位*)
g_bZAxisZero :=FUN_SingalLogic(g_bFilter_ZAxisZero,bZAxisZero);  
(*A轴零位，正负限位滤波*)
Filter_67(nFilterTime,g_bAAxisZeroLogic,g_biAAxisHomeSignal,g_boFilter_AAxisZero);
Filter_68(nFilterTime,g_bAAxisPosLimitLogic,g_biAAxisPosLimit,g_boFilter_AAxisPosLimit);
Filter_69(nFilterTime,g_bAAxisNegLimitLogic,g_biAAxisNegLimit,g_boFilter_AAxisNegLimit);
IF g_nFAxisControl=2 THEN
  IF nFAxisHomeSignal = 0 THEN
    bFAxisHomeZero := FUN_SingalLogic(g_biFAxisHomeSignal,bFAxisZero);
  ELSIF nFAxisHomeSignal = 1 THEN
    bFAxisHomeZero := FUN_SingalLogic(g_biFAxisPosLimit,bFAxisPosLimit);
  ELSE
    bFAxisHomeZero := FUN_SingalLogic(g_biFAxisNegLimit,bFAxisNegLimit);
  END_IF;
  g_nFAxisHomeSignal := nFAxisHomeSignal;
  (*滤波后的正负零位*)
   Filter_4(nFilterTime,bFAxisPosLimit,g_biFAxisPosLimit,g_bFilter_FAxisPosLimit);
   Filter_5(nFilterTime,bFAxisNegLimit,g_biFAxisNegLimit,g_bFilter_FAxisNegLimit);
   Filter_6(nFilterTime,bFAxisZero,bFAxisHomeZero,g_bFilter_FAxisZero);
  (*F轴正硬限位*)
  g_bFAxisPosLimit :=FUN_SingalLogic(g_bFilter_FAxisPosLimit,bFAxisPosLimit);
  (*F轴负硬限位*)
  g_bFAxisNegLimit := FUN_SingalLogic(g_bFilter_FAxisNegLimit,bFAxisNegLimit);
  (*F轴零位*)
  g_bFAxisZero :=bFAxisHomeZero;
END_IF;

IF g_bU2AxisEnable THEN
  IF g_U2AxisHomeSignal = 0 THEN
    bU2AxisHomeZero := FUN_SingalLogic(g_biUAxisHomeSignal,bUAxisZero);
  ELSIF g_U2AxisHomeSignal = 1 THEN
     bU2AxisHomeZero := FUN_SingalLogic(g_biUAxisPosLimit,bUAxisPosLimit);
  ELSE
     bU2AxisHomeZero := FUN_SingalLogic(g_biUAxisNegLimit,bUAxisNegLimit);
  END_IF;
  (*滤波后的正负零位*)
   Filter_7(nFilterTime,bUAxisPosLimit,g_biUAxisPosLimit,g_bFilter_U2AxisPosLimit);
   Filter_8(nFilterTime,bUAxisNegLimit,g_biUAxisNegLimit,g_bFilter_U2AxisNegLimit);
   (*Filter_9(nFilterTime,bUAxisZero,bU2AxisHomeZero,g_bFilter_U2AxisZero);*)
  (*U2轴正硬限位*)
  g_bUAxisPosLimit :=FUN_SingalLogic(g_bFilter_U2AxisPosLimit,bUAxisPosLimit);
  (*U2轴负硬限位*)
  g_bUAxisNegLimit :=FUN_SingalLogic(g_bFilter_U2AxisNegLimit,bUAxisNegLimit);
  (*U2轴零位*)
  g_bUAxisZero :=bU2AxisHomeZero;
END_IF;

IF g_nMachineType=6 OR g_nMachineType = 19 THEN(*3卡盘*)
  (*对零位信号进行特殊处理：使用限位回零时，将限位转一道当成零位*)
  IF nU3HomeSignalType = 0 THEN
    bU3HomeZero := g_biU3AxisZero;
  ELSIF nSustainHomeSignal1 = 1 THEN
    bU3HomeZero := g_biU3AxisPosLimit;
  ELSE
    bU3HomeZero := g_biU3AxisNegLimit;
  END_IF;
  IF nY3HomeSignalType = 0 THEN
    bY3HomeZero := g_biY3AxisZero;
  ELSIF nSustainHomeSignal1 = 1 THEN
    bY3HomeZero := g_biY3AxisPosLimit;
  ELSE
    bY3HomeZero := g_biY3AxisNegLimit;
  END_IF;
  IF nY2HomeSignalType = 0 THEN
    bY2HomeZero := g_biY2AxisZero;
  ELSIF nSustainHomeSignal1 = 1 THEN
    bY2HomeZero := g_biY2AxisPosLimit;
  ELSE
    bY2HomeZero := g_biY2AxisNegLimit;
  END_IF;
  g_nU3HomeSignalType := nU3HomeSignalType;
  g_nY3HomeSignalType := nY3HomeSignalType;
  g_nY2HomeSignalType := nY2HomeSignalType;
  (*滤波后的正负零位*)
   Filter_58(nFilterTime,bU3AxisPosLimit,g_biU3AxisPosLimit,g_bFilter_U3AxisPosLimit);
   Filter_59(nFilterTime,bU3AxisNegLimit,g_biU3AxisNegLimit,g_bFilter_U3AxisNegLimit);
   Filter_60(nFilterTime,bU3AxisZero,bU3HomeZero,g_bFilter_U3AxisZero);
   Filter_61(nFilterTime,bY3AxisPosLimit,g_biY3AxisPosLimit,g_bFilter_Y3AxisPosLimit);
   Filter_62(nFilterTime,bY3AxisNegLimit,g_biY3AxisNegLimit,g_bFilter_Y3AxisNegLimit);
   Filter_63(nFilterTime,bY3AxisZero,bY3HomeZero,g_bFilter_Y3AxisZero);
   Filter_64(nFilterTime,bY2AxisPosLimit,g_biY2AxisPosLimit,g_bFilter_Y2AxisPosLimit);
   Filter_65(nFilterTime,bY2AxisNegLimit,g_biY2AxisNegLimit,g_bFilter_Y2AxisNegLimit);
   Filter_66(nFilterTime,bY2AxisZero,bY2HomeZero,g_bFilter_Y2AxisZero);

  (*U3轴正硬限位*)
  g_bU3AxisPosLimit :=FUN_SingalLogic(g_bFilter_U3AxisPosLimit,bU3AxisPosLimit);
  (*U3轴负硬限位*)
  g_bU3AxisNegLimit :=FUN_SingalLogic(g_bFilter_U3AxisNegLimit,bU3AxisNegLimit);
  (*U3轴零位*)
  g_bU3AxisZero :=FUN_SingalLogic(g_bFilter_U3AxisZero,bU3AxisZero);
  (*Y3轴正硬限位*)
  g_bY3AxisPosLimit :=FUN_SingalLogic(g_bFilter_Y3AxisPosLimit,bY3AxisPosLimit);
  (*Y3轴负硬限位*)
  g_bY3AxisNegLimit :=FUN_SingalLogic(g_bFilter_Y3AxisNegLimit,bY3AxisNegLimit);
  (*Y3轴零位*)
  g_bY3AxisZero :=FUN_SingalLogic(g_bFilter_Y3AxisZero,bY3AxisZero);
  (*Y2轴正硬限位*)
  g_bY2AxisPosLimit :=FUN_SingalLogic(g_bFilter_Y2AxisPosLimit,bY2AxisPosLimit);
  (*Y2轴负硬限位*)
  g_bY2AxisNegLimit :=FUN_SingalLogic(g_bFilter_Y2AxisNegLimit,bY2AxisNegLimit);
  (*Y2轴零位*)
  g_bY2AxisZero :=FUN_SingalLogic(g_bFilter_Y2AxisZero,bY2AxisZero);
  (*Y1轴正硬限位*)
  g_bY1AxisPosLimit :=FUN_SingalLogic(g_biY1AxisPosLimit,bY1AxisPosLimit);
  (*Y1轴负硬限位*)
  g_bY1AxisNegLimit :=FUN_SingalLogic(g_biY1AxisNegLimit,bY1AxisNegLimit);
  (*Y1轴零位*)
  g_bY1AxisZero :=FUN_SingalLogic(g_biY1AxisZero,bY1AxisZero);
  (*三卡盘防撞信号*)
  g_bClaw3YY2Collision:= FUN_SingalLogic(g_biClaw3YY2Collision,bClaw3YY2Collision);
  g_bClaw3Y2Y3Collision:= FUN_SingalLogic(g_biClaw3Y2Y3Collision,bClaw3Y2Y3Collision);
END_IF;
(*控制面板启动信号*)
RT_CtrlPanelStart(CLK := g_bControlPanelStrat);
IF RT_CtrlPanelStart.Q THEN
  g_bSendControlPanelStrat := TRUE;
END_IF;
IF NOT g_bHMIStart_Up  THEN
  g_bSendControlPanelStrat := FALSE;
END_IF;
Filter_StartCmd(nFilterTime,bControlPanelStrat,g_biControlPanelStrat,bFilterControlPanelStrat);
