  g_nSustainHomeSignal5 := nSustainHomeSignal5;
  g_nSustainHomeSignal6 := nSustainHomeSignal6;

  (*滤波后的正负零位*)
  Filter_28(nFilterTime,bSusTain4HomeCal,g_biSusTain4HomeCal,g_bFilter_SusTainHomeCal4);
  Filter_29(nFilterTime,bSusTain5HomeCal,g_biSusTain5HomeCal,g_bFilter_SusTainHomeCal5);
  Filter_30(nFilterTime,bSusTain6HomeCal,g_biSusTain6HomeCal,g_bFilter_SusTainHomeCal6);
  Filter_FrontSustain4Zero(nFilterTime,bAntiRejection2Zero,g_biAntiRejection2Zero,bFrontSustain4Filter_Zero);

  Filter_31(nFilterTime,bSustain4PosLimit,g_biSustain4PosLimit,g_bFilter_SustainPosLimit4);
  Filter_32(nFilterTime,bSustain5PosLimit,g_biSustain5PosLimit,g_bFilter_SustainPosLimit5);
  Filter_33(nFilterTime,bSustain6PosLimit,g_biSustain6PosLimit,g_bFilter_SustainPosLimit6); 
  Filter_FrontSustain4PosLimit(nFilterTime,bAntiRejection2PosLimit,g_biAntiRejection2PosLimit,bFrontSustain4Filter_PosLimit); 

  Filter_34(nFilterTime,bSustain4NegLimit,g_biSustain4NegLimit,g_bFilter_SustainNegLimit4);
  Filter_35(nFilterTime,bSustain5NegLimit,g_biSustain5NegLimit,g_bFilter_SustainNegLimit5);
  Filter_36(nFilterTime,bSustain6NegLimit,g_biSustain6NegLimit,g_bFilter_SustainNegLimit6);
  Filter_FrontSustain4NegLimit(nFilterTime,bAntiRejection2NegLimit,g_biAntiRejection2NegLimit,bFrontSustain4Filter_NegLimit);




   (*对零位信号进行特殊处理：使用限位回零时，将限位转一道当成零位,回原检测的零位信号不能滤波*)
  IF nSustainHomeSignal4 = 0 THEN
    bSustainAxisHomeZero4 := g_biSusTain4HomeCal;
    g_bSusTain4HomeCal := FUN_SingalLogic(bSustainAxisHomeZero4,bSusTain4HomeCal);
  ELSIF nSustainHomeSignal4 = 1 THEN
    bSustainAxisHomeZero4 := g_biSustain4PosLimit;
    g_bSusTain4HomeCal := FUN_SingalLogic(bSustainAxisHomeZero4,bSustain4PosLimit);
  ELSE
    bSustainAxisHomeZero4 := g_biSustain4NegLimit;
    g_bSusTain4HomeCal := FUN_SingalLogic(bSustainAxisHomeZero4,bSustain4NegLimit);
  END_IF;


  IF nSustainHomeSignal5 = 0 THEN
    bSustainAxisHomeZero5 := g_biSusTain5HomeCal;
    g_bSusTain5HomeCal := FUN_SingalLogic(bSustainAxisHomeZero5,bSusTain5HomeCal);
  ELSIF nSustainHomeSignal5 = 1 THEN
    bSustainAxisHomeZero5 := g_biSustain5PosLimit;
    g_bSusTain5HomeCal := FUN_SingalLogic(bSustainAxisHomeZero5,bSustain5PosLimit);
  ELSE
    bSustainAxisHomeZero5 := g_biSustain5NegLimit;
    g_bSusTain5HomeCal := FUN_SingalLogic(bSustainAxisHomeZero5,bSustain5NegLimit);
  END_IF;


  IF nSustainHomeSignal6 = 0 THEN
    bSustainAxisHomeZero6 := g_biSusTain6HomeCal;
     g_bSusTain6HomeCal := FUN_SingalLogic(bSustainAxisHomeZero6,bSusTain6HomeCal);
  ELSIF nSustainHomeSignal6 = 1 THEN
    bSustainAxisHomeZero6 := g_biSustain6PosLimit;
    g_bSusTain6HomeCal := FUN_SingalLogic(bSustainAxisHomeZero6,bSustain6PosLimit);
  ELSE
    bSustainAxisHomeZero6 := g_biSustain6NegLimit;
    g_bSusTain6HomeCal := FUN_SingalLogic(bSustainAxisHomeZero6,bSustain6NegLimit);
  END_IF; 


 IF g_AntiRejection2HomeSignal = 0 THEN
    g_boAntiRejection2HomeSignal := g_biAntiRejection2HomeSignal;
      g_bAntiRejection2HomeSignal :=FUN_SingalLogic(g_boAntiRejection2HomeSignal,bAntiRejection2Zero);
  ELSIF g_AntiRejection2HomeSignal = 1 THEN
    g_boAntiRejection2HomeSignal := g_biAntiRejection2PosLimit;
      g_bAntiRejection2HomeSignal :=FUN_SingalLogic(g_boAntiRejection2HomeSignal,bAntiRejection2PosLimit);
  ELSE
    g_boAntiRejection2HomeSignal := g_biAntiRejection2NegLimit;
      g_bAntiRejection2HomeSignal :=FUN_SingalLogic(g_boAntiRejection2HomeSignal,bAntiRejection2NegLimit);
  END_IF;




  (*前浮动支撑轴*)

  g_bSustain4PosLimit := FUN_SingalLogic(g_bFilter_SustainPosLimit4,bSustain4PosLimit);
  g_bSustain5PosLimit := FUN_SingalLogic(g_bFilter_SustainPosLimit5,bSustain5PosLimit);
  g_bSustain6PosLimit := FUN_SingalLogic(g_bFilter_SustainPosLimit6,bSustain6PosLimit);
  g_bAntiRejection2PosLimit :=FUN_SingalLogic(bFrontSustain4Filter_PosLimit,bAntiRejection2PosLimit);

  g_bSustain4NegLimit := FUN_SingalLogic(g_bFilter_SustainNegLimit4,bSustain4NegLimit);
  g_bSustain5NegLimit := FUN_SingalLogic(g_bFilter_SustainNegLimit5,bSustain5NegLimit);
  g_bSustain6NegLimit := FUN_SingalLogic(g_bFilter_SustainNegLimit6,bSustain6NegLimit);
  g_bAntiRejection2NegLimit :=FUN_SingalLogic(bFrontSustain4Filter_NegLimit,bAntiRejection2NegLimit);


  g_bAntiRejection2Zero :=FUN_SingalLogic(g_biAntiRejection2Zero,bFrontSustain4Filter_Zero);






END_IF;

IF g_bDustEnable THEN
  (*抽尘轴回零信号*)
  (*对零位信号进行特殊处理：使用限位回零时，将限位转一道当成零位*)
  IF nDustHomeSignal = 0 THEN
    bDustAxisHomeZero := g_biDustHomeCal;
     g_bDustHomeCal := FUN_SingalLogic(bDustAxisHomeZero,bDustHomeCal);
  ELSIF nDustHomeSignal = 1 THEN
    bDustAxisHomeZero := g_biDustAxisPosLimit;
     g_bDustHomeCal := FUN_SingalLogic(bDustAxisHomeZero,bDustAxisPosLimit);
  ELSE
    bDustAxisHomeZero := g_biDustAxisNegLimit;
     g_bDustHomeCal := FUN_SingalLogic(bDustAxisHomeZero,bDustAxisNegLimit);
  END_IF;
  g_nDustHomeSignal := nDustHomeSignal;
  Filter_43(nFilterTime,bDustHomeCal,bDustAxisHomeZero,g_bFilter_DustHomeCal); 
  Filter_44(nFilterTime,bDustAxisPosLimit,g_biDustAxisPosLimit,g_bFilter_DustAxisPosLimit); 
  Filter_45(nFilterTime,bDustAxisNegLimit,g_biDustAxisNegLimit,g_bFilter_DustAxisNegLimit);


  g_bDustAxisPosLimit := FUN_SingalLogic(g_bFilter_DustAxisPosLimit,bDustAxisPosLimit);
  g_bDustAxisNegLimit := FUN_SingalLogic(g_bFilter_DustAxisNegLimit,bDustAxisNegLimit);
END_IF;

IF g_nMachineType = 1 OR g_nMachineType = 7 THEN
  (*标克下料机信号检测*)
  g_bDustZero := FUN_SingalLogic(g_biDustAxisZero,bDustAxisZero);
  g_bFeedingZero := FUN_SingalLogic(g_biFeedingZero,bFeedingZero);
  g_bFeedingPosLimit := FUN_SingalLogic(g_biFeedingPosLimit,bFeedingPosLimit);
  g_bFeedingNegLimit := FUN_SingalLogic(g_biFeedingNegLimit,bFeedingNegLimit);
  g_bDustPosLimit := FUN_SingalLogic(g_biDustPosLimit,bDustPosLimit);
  g_bDustNegLimit := FUN_SingalLogic(g_biDustNegLimit,bDustNegLimit);
  g_bFixedLenZero := FUN_SingalLogic(g_biFixedLenZero,bFixedLenZero);
  g_bFixedLenPosLimit := FUN_SingalLogic(g_biFixedLenPosLimit,bFixedLenPosLimit);
  g_bFixedLenNegLimit := FUN_SingalLogic(g_biFixedLenNegLimit,bFixedLenNegLimit);
END_IF;

IF g_nMachineType = 4 OR g_nMachineType = 9 THEN

  Filter_55(nFilterTime,bDDAxisPosLimit,g_biDDAxisPosLimit,g_bFilter_DDAxisPosLimit); 
  Filter_56(nFilterTime,bDDAxisNegLimit,g_biDDAxisNegLimit,g_bFilter_DDAxisNegLimit); 
  Filter_57(nFilterTime,bDDAxisZero,g_biDDAxisZero,g_bFilter_DDAxisZero); 
  (*鼎点轴正硬限位*)
  g_bDDAxisPosLimit :=FUN_SingalLogic(g_bFilter_DDAxisPosLimit,bDDAxisPosLimit);
  (*鼎点轴负硬限位*)
  g_bDDAxisNegLimit :=FUN_SingalLogic(g_bFilter_DDAxisNegLimit,bDDAxisNegLimit);
  (*鼎点轴零位*)
  g_bDDAxisZero :=FUN_SingalLogic(g_bFilter_DDAxisZero,bDDAxisZero);
END_IF;
IF g_bDustCylinderEnable THEN
	(*抽尘气缸*)
	Filter_91(LREAL_TO_TIME(FUN_MSTOS(LREAL_TO_DINT(dDustCyl1DownFilterTime))),bGeneralDustCylinderUpInPlace,g_biGeneralDustCylinderUpInPlace,bGeneralDustCylinderUpInPlaceFilter);
	g_bGeneralDustCylinderUpInPlace := FUN_SingalLogic(bGeneralDustCylinderUpInPlaceFilter,bGeneralDustCylinderUpInPlace);
	Filter_83(LREAL_TO_TIME(FUN_MSTOS(LREAL_TO_DINT(dDustCyl1DownFilterTime))),bGeneralDustCylinderDownInPlace,g_biGeneralDustCylinderDownInPlace,bGeneralDustCylinderDownInPlaceFilter);
	g_bGeneralDustCylinderDownInPlace := FUN_SingalLogic(bGeneralDustCylinderDownInPlaceFilter,bGeneralDustCylinderDownInPlace);

	Filter_92(LREAL_TO_TIME(FUN_MSTOS(LREAL_TO_DINT(dDustCyl2DownFilterTime))),bDustCylinder1UpInPlace,g_biDustCylinder1UpInPlace,bDustCylinder1UpInPlaceFilter);
	g_bDustCylinder1UpInPlace := FUN_SingalLogic(bDustCylinder1UpInPlaceFilter,bDustCylinder1UpInPlace);

	Filter_84(LREAL_TO_TIME(FUN_MSTOS(LREAL_TO_DINT(dDustCyl2DownFilterTime))),bDustCylinder1DownInPlace,g_biDustCylinder1DownInPlace,bDustCylinder1DownInPlaceFilter);
	g_bDustCylinder1DownInPlace := FUN_SingalLogic(bDustCylinder1DownInPlaceFilter,bDustCylinder1DownInPlace);

	Filter_93(LREAL_TO_TIME(FUN_MSTOS(LREAL_TO_DINT(dDustCyl3DownFilterTime))),bDustCylinder2UpInPlace,g_biDustCylinder2UpInPlace,bDustCylinder2UpInPlaceFilter);
	g_bDustCylinder2UpInPlace := FUN_SingalLogic(bDustCylinder2UpInPlaceFilter,bDustCylinder2UpInPlace);
	Filter_85(LREAL_TO_TIME(FUN_MSTOS(LREAL_TO_DINT(dDustCyl3DownFilterTime))),bDustCylinder2DownInPlace,g_biDustCylinder2DownInPlace,bDustCylinder2DownInPlaceFilter);
	g_bDustCylinder2DownInPlace := FUN_SingalLogic(bDustCylinder2DownInPlaceFilter,bDustCylinder2DownInPlace);

END_IF;
IF g_bIsConfigDoubleDustChangeCyl THEN
  Filter_doubledustup(LREAL_TO_TIME(FUN_MSTOS(LREAL_TO_DINT(dDoubleDustChangeCylDownFilterTime))),bDoubleDustChangeCylinderUpInPlace,g_biDustChangeCylinderUpLimitSignal,bDoubleDustChangeCylinderUpInPlaceFilter);
  g_bDoubleDustChangeCylUpInPlace := FUN_SingalLogic(bDoubleDustChangeCylinderUpInPlaceFilter,bDoubleDustChangeCylinderUpInPlace);
  Filter_doubledustdown(LREAL_TO_TIME(FUN_MSTOS(LREAL_TO_DINT(dDoubleDustChangeCylDownFilterTime))),bDoubleDustChangeCylinderDownInPlace,g_biDustChangeCylinderDownLimitSignal,bDoubleDustChangeCylinderDownInPlaceFilter);
  g_bDoubleDustChangeCylDownInPlace := FUN_SingalLogic(bDoubleDustChangeCylinderDownInPlaceFilter,bDoubleDustChangeCylinderDownInPlace);

END_IF;
IF g_bUseCommonAxis1 OR g_bUseCommonAxis2 OR g_bUseCommonAxis3 OR g_nMachineType = 19 THEN
	(*通用轴限位信号*)
	(*对零位信号进行特殊处理：使用限位回零时，将限位转一道当成零位*)
	  IF nGeneralHomeSignal1 = 0 THEN
		bGeneralAxisHomeZero1 := g_biGeneralAxis1HomeSignal;
        g_bGeneralAxis1Zero := FUN_SingalLogic(bGeneralAxisHomeZero1,bGeneralAxis1Zero);
	  ELSIF nGeneralHomeSignal1 = 1 THEN
		bGeneralAxisHomeZero1 := g_biGeneral1PosLimit;
        g_bGeneralAxis1Zero := FUN_SingalLogic(bGeneralAxisHomeZero1,bGeneral1PosLimit);
	  ELSE
		bGeneralAxisHomeZero1 := g_biGeneral1NegLimit;
        g_bGeneralAxis1Zero := FUN_SingalLogic(bGeneralAxisHomeZero1,bGeneral1NegLimit);
	  END_IF;
	  IF nGeneralHomeSignal2 = 0 THEN
		bGeneralAxisHomeZero2 := g_biGeneralAxis2HomeSignal;
        g_bGeneralAxis2Zero := FUN_SingalLogic(bGeneralAxisHomeZero2,bGeneralAxis2Zero);
	  ELSIF nGeneralHomeSignal2 = 1 THEN
		bGeneralAxisHomeZero2 := g_biGeneral2PosLimit;
        g_bGeneralAxis2Zero := FUN_SingalLogic(bGeneralAxisHomeZero2,bGeneral2PosLimit);
	  ELSE
		bGeneralAxisHomeZero2 := g_biGeneral2NegLimit;
        g_bGeneralAxis2Zero := FUN_SingalLogic(bGeneralAxisHomeZero2,bGeneral2NegLimit);
	  END_IF;
	  g_nGeneralHomeSignal1 := nGeneralHomeSignal1;
	  g_nGeneralHomeSignal2 := nGeneralHomeSignal2;
	  Filter_37(nFilterTime,bGeneralAxis1Zero,bGeneralAxisHomeZero1,g_bFilter_GeneralAxisZero1); 
	  Filter_38(nFilterTime,bGeneral1PosLimit,g_biGeneral1PosLimit,g_bFilter_GeneralPosLimit1); 
	  Filter_39(nFilterTime,bGeneral1NegLimit,g_biGeneral1NegLimit,g_bFilter_GeneralNegLimit1);

	  Filter_40(nFilterTime,bGeneralAxis2Zero,bGeneralAxisHomeZero2,g_bFilter_GeneralAxisZero2); 
	  Filter_41(nFilterTime,bGeneral2PosLimit,g_biGeneral2PosLimit,g_bFilter_GeneralPosLimit2); 
	  Filter_42(nFilterTime,bGeneral2NegLimit,g_biGeneral2NegLimit,g_bFilter_GeneralNegLimit2);


	g_bGeneral1PosLimit := FUN_SingalLogic(g_bFilter_GeneralPosLimit1,bGeneral1PosLimit);
	g_bGeneral1NegLimit := FUN_SingalLogic(g_bFilter_GeneralNegLimit1,bGeneral1NegLimit);


	g_bGeneral2PosLimit := FUN_SingalLogic(g_bFilter_GeneralPosLimit2,bGeneral2PosLimit);
	g_bGeneral2NegLimit := FUN_SingalLogic(g_bFilter_GeneralNegLimit2,bGeneral2NegLimit);
	(*通用轴3限位信号*)

	(*对零位信号进行特殊处理：使用限位回零时，将限位转一道当成零位*)

	  IF nWAxisHomeSignalType = 0 THEN
		bGeneralAxisHomeZero3 := g_biDDAxisZero;
		g_bDDAxisZero :=FUN_SingalLogic(bGeneralAxisHomeZero3,bDDAxisZero);
	  ELSIF nWAxisHomeSignalType = 1 THEN
		bGeneralAxisHomeZero3 := g_biDDAxisPosLimit;
		g_bDDAxisZero :=FUN_SingalLogic(bGeneralAxisHomeZero3,bDDAxisPosLimit);
	  ELSE
		bGeneralAxisHomeZero3 := g_biDDAxisNegLimit;
		g_bDDAxisZero :=FUN_SingalLogic(bGeneralAxisHomeZero3,bDDAxisNegLimit);
	  END_IF;
	  g_nWAxisHomeSignalType := nWAxisHomeSignalType;
	  Filter_57(nFilterTime,bDDAxisZero,bGeneralAxisHomeZero3,g_bFilter_DDAxisZero); 
	  Filter_55(nFilterTime,bDDAxisPosLimit,g_biDDAxisPosLimit,g_bFilter_DDAxisPosLimit); 
	  Filter_56(nFilterTime,bDDAxisNegLimit,g_biDDAxisNegLimit,g_bFilter_DDAxisNegLimit); 

	  (*鼎点轴正硬限位*)
	  g_bDDAxisPosLimit :=FUN_SingalLogic(g_bFilter_DDAxisPosLimit,bDDAxisPosLimit);
	  (*鼎点轴负硬限位*)
	  g_bDDAxisNegLimit :=FUN_SingalLogic(g_bFilter_DDAxisNegLimit,bDDAxisNegLimit);

END_IF;
IF g_nAntiRejectionFun = 2 THEN
  (*防甩轴1正硬限位*)
  g_bAntiRejection1PosLimit :=FUN_SingalLogic(g_biAntiRejection1PosLimit,bAntiRejection1PosLimit);
  (*防甩轴1负硬限位*)
  g_bAntiRejection1NegLimit :=FUN_SingalLogic(g_biAntiRejection1NegLimit,bAntiRejection1NegLimit);
  (*防甩轴1零位信号*)
  g_bAntiRejection1Zero :=FUN_SingalLogic(g_biAntiRejection1Zero,bAntiRejection1Zero);




END_IF;
IF g_bIsConfigDustAxis2 THEN
  (*防甩轴3正硬限位*)
  g_bAntiRejection3PosLimit :=FUN_SingalLogic(g_biAntiRejection3PosLimit,bAntiRejection3PosLimit);
  (*防甩轴3负硬限位*)
  g_bAntiRejection3NegLimit :=FUN_SingalLogic(g_biAntiRejection3NegLimit,bAntiRejection3NegLimit);
  (*防甩轴3零位信号*)
  g_bAntiRejection3Zero :=FUN_SingalLogic(g_biAntiRejection3Zero,bAntiRejection3Zero);


  IF g_AntiRejection3HomeSignal = 0 THEN
    g_boAntiRejection3HomeSignal := g_bAntiRejection3Zero;
  ELSIF g_AntiRejection3HomeSignal = 1 THEN
    g_boAntiRejection3HomeSignal := g_bAntiRejection3PosLimit;
  ELSE
    g_boAntiRejection3HomeSignal := g_bAntiRejection3NegLimit;
  END_IF;

END_IF;

  (*防甩轴4正硬限位*)
  g_bAntiRejection4PosLimit :=FUN_SingalLogic(g_biAntiRejection4PosLimit,bAntiRejection4PosLimit);
  (*防甩轴4负硬限位*)
  g_bAntiRejection4NegLimit :=FUN_SingalLogic(g_biAntiRejection4NegLimit,bAntiRejection4NegLimit);
  (*防甩轴4零位信号*)
  g_bAntiRejection4Zero :=FUN_SingalLogic(g_biAntiRejection4Zero,bAntiRejection4Zero);
  (*防甩轴5正硬限位*)
  g_bAntiRejection5PosLimit :=FUN_SingalLogic(g_biAntiRejection5PosLimit,bAntiRejection5PosLimit);
  (*防甩轴5负硬限位*)
  g_bAntiRejection5NegLimit :=FUN_SingalLogic(g_biAntiRejection5NegLimit,bAntiRejection5NegLimit);
  (*防甩轴5零位信号*)
  g_bAntiRejection5Zero :=FUN_SingalLogic(g_biAntiRejection5Zero,bAntiRejection5Zero);
 (*防甩轴6正硬限位*)
  g_bAntiRejection6PosLimit :=FUN_SingalLogic(g_biAntiRejection6PosLimit,bAntiRejection6PosLimit);
  (*防甩轴6负硬限位*)
  g_bAntiRejection6NegLimit :=FUN_SingalLogic(g_biAntiRejection6NegLimit,bAntiRejection6NegLimit);
  (*防甩轴6零位信号*)
  g_bAntiRejection6Zero :=FUN_SingalLogic(g_biAntiRejection6Zero,bAntiRejection6Zero);
  (*z轴安全位置信号*)
  g_bZAxisSafeCheckSignal := FUN_SingalLogic(g_biZAxisSafeCheckSignal,bZAxisSafeCheckSignal);
  (*x轴安全位置信号*)
  g_bXAxisSafeCheckSignal := FUN_SingalLogic(g_biXAxisSafeCheckSignal,bXAxisSafeCheckSignal);

  IF g_AntiRejection6HomeSignal = 0 THEN
    g_boAntiRejection6HomeSignal := g_bAntiRejection6Zero;
  ELSIF g_AntiRejection6HomeSignal = 1 THEN
    g_boAntiRejection6HomeSignal := g_bAntiRejection6PosLimit;
  ELSE
    g_boAntiRejection6HomeSignal := g_bAntiRejection6NegLimit;
  END_IF;
  (*跟随Y轴的信号*)

  bMainAvoidAxisPosLimit := FUN_SingalLogic(g_bYAxisPosLimitLogic,g_biFilter_YAxisPosLimit);
  bMainAvoidAxisNegLimit := FUN_SingalLogic(g_bYAxisNegLimitLogic,g_biFilter_YAxisNegLimit);
  bMainAvoidAxisZero := FUN_SingalLogic(g_bYAxisZeroLogic,g_biFilter_YAxisZero);

  IF g_AntiRejection4HomeSignal = 0 THEN
    g_boAntiRejection4HomeSignal := bMainAvoidAxisZero;
  ELSIF g_AntiRejection4HomeSignal = 1 THEN
    g_boAntiRejection4HomeSignal := bMainAvoidAxisPosLimit;
  ELSE
    g_boAntiRejection4HomeSignal := bMainAvoidAxisNegLimit;
  END_IF;

  IF g_AntiRejection5HomeSignal = 0 THEN
    g_boAntiRejection5HomeSignal := g_bAntiRejection5Zero;
  ELSIF g_AntiRejection5HomeSignal = 1 THEN
